changeSet.sql:
DECLARE @Now DATETIME2 = SYSUTCDATETIME(); INSERT INTO app.FeatureDefinitions (Id, Code, Name, Description, Category, IsActive, Scope, ConsumesLicense, CreatedAt, UpdatedAt) VALUES ('a2222222-2222-4222-8222-222222222002', N'GYM_EXPENSE_MANAGEMENT', N'Expense management', N'Record and review gym operating expenses.', N'Platform', 1, N'Tenant', 0, @Now, @Now);
INSERT INTO app.PlanFeatures (Id, PlanId, FeatureCode, [Enabled], CreatedAt, UpdatedAt) SELECT NEWID(), p.Id, N'GYM_EXPENSE_MANAGEMENT', CASE WHEN p.Code IN (N'BASIC', N'PRO', N'ENTERPRISE') THEN 1 ELSE 0 END, @Now, @Now FROM app.Plans p;
INSERT INTO app.Permissions (Id, Code, Name, Description, CreatedAt, UpdatedAt) VALUES ('22222222-2222-4222-8222-222222222065', N'EXPENSE_READ', N'Read expenses', N'Read expenses, categories, and expense summaries.', @Now, @Now), ('22222222-2222-4222-8222-222222222066', N'EXPENSE_CREATE', N'Create expenses', N'Record an expense.', @Now, @Now), ('22222222-2222-4222-8222-222222222067', N'EXPENSE_UPDATE', N'Update expenses', N'Update an active expense.', @Now, @Now), ('22222222-2222-4222-8222-222222222068', N'EXPENSE_VOID', N'Void expenses', N'Void an expense without deleting its history.', @Now, @Now), ('22222222-2222-4222-8222-222222222069', N'EXPENSE_CATEGORY_MANAGE', N'Manage expense categories', N'Create, update, and deactivate expense categories.', @Now, @Now);
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code IN (N'EXPENSE_READ', N'EXPENSE_CREATE', N'EXPENSE_UPDATE', N'EXPENSE_VOID', N'EXPENSE_CATEGORY_MANAGE') WHERE r.Name IN (N'SuperAdmin', N'GymOwner', N'GymManager');
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code IN (N'EXPENSE_READ', N'EXPENSE_CREATE') WHERE r.Name = N'Receptionist';

